    __SIMD_fastpackwithoutmask6_16(in, out);
    return;
  case 7:
    __SIMD_fastpackwithoutmask7_16(in, out);
    return;
  case 8:
    __SIMD_fastpackwithoutmask8_16(in, out);
    return;
  case 9:
    __SIMD_fastpackwithoutmask9_16(in, out);
    return;
  case 10:
    __SIMD_fastpackwithoutmask10_16(in, out);
    return;
  case 11:
    __SIMD_fastpackwithoutmask11_16(in, out);
    return;
  case 12:
    __SIMD_fastpackwithoutmask12_16(in, out);
    return;
  case 13:
    __SIMD_fastpackwithoutmask13_16(in, out);
    return;
  case 14:
